import React, { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import './ModernChat.css';

const ModernChat = ({ isOpen, onClose }) => {
  const [messages, setMessages] = useState([
    {
      id: 1,
      type: 'nova',
      text: 'Welcome! I\'m Nova, your AI assistant. How can I help you today?',
      timestamp: new Date()
    }
  ]);
  const [inputValue, setInputValue] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const messagesEndRef = useRef(null);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSendMessage = (e) => {
    e.preventDefault();
    
    if (!inputValue.trim()) return;

    // Add user message
    const userMessage = {
      id: messages.length + 1,
      type: 'user',
      text: inputValue,
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMessage]);
    setInputValue('');

    // Simulate Nova response
    setIsTyping(true);
    setTimeout(() => {
      const novaMessage = {
        id: messages.length + 2,
        type: 'nova',
        text: 'I understand. Let me help you with that...',
        timestamp: new Date()
      };
      setMessages(prev => [...prev, novaMessage]);
      setIsTyping(false);
    }, 1500);
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <>
          {/* Backdrop */}
          <motion.div
            className="chat-backdrop"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
          />

          {/* Chat Window */}
          <motion.div
            className="modern-chat-interface active"
            initial={{ y: '100vh', scale: 0.8, opacity: 0 }}
            animate={{ y: 0, scale: 1, opacity: 1 }}
            exit={{ y: '100vh', scale: 0.8, opacity: 0 }}
            transition={{ type: 'spring', damping: 25, stiffness: 200 }}
          >
            {/* Header */}
            <div className="chat-header">
              <div className="chat-header-left">
                <div className="nova-avatar">
                  <i className="fas fa-robot"></i>
                </div>
                <div className="chat-header-info">
                  <div className="chat-title">NOVA AI</div>
                  <div className="chat-status">
                    <span className="status-dot"></span>
                    Online
                  </div>
                </div>
              </div>
              <div className="chat-header-controls">
                <button className="chat-minimize-btn">
                  <i className="fas fa-minus"></i>
                </button>
                <button className="chat-close-btn" onClick={onClose}>
                  <i className="fas fa-times"></i>
                </button>
              </div>
            </div>

            {/* Messages */}
            <div className="modern-chat-messages">
              {messages.map((message) => (
                <motion.div
                  key={message.id}
                  className={`chat-message ${message.type}`}
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ duration: 0.3 }}
                >
                  <div className={`message-avatar ${message.type === 'nova' ? 'nova-avatar-small' : 'user-avatar'}`}>
                    {message.type === 'nova' ? <i className="fas fa-robot"></i> : 'U'}
                  </div>
                  <div className="message-content">
                    <div className="message-bubble">
                      {message.text}
                    </div>
                  </div>
                </motion.div>
              ))}

              {isTyping && (
                <motion.div
                  className="chat-message"
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                >
                  <div className="message-avatar nova-avatar-small">
                    <i className="fas fa-robot"></i>
                  </div>
                  <div className="message-content">
                    <div className="typing-bubble">
                      <div className="typing-dots">
                        <div className="typing-dot"></div>
                        <div className="typing-dot"></div>
                        <div className="typing-dot"></div>
                      </div>
                    </div>
                  </div>
                </motion.div>
              )}

              <div ref={messagesEndRef} />
            </div>

            {/* Input Area */}
            <div className="modern-chat-input-area">
              <form onSubmit={handleSendMessage} className="chat-input-container">
                <div className="input-wrapper">
                  <input
                    type="text"
                    className="modern-chat-input"
                    placeholder="Type your message..."
                    value={inputValue}
                    onChange={(e) => setInputValue(e.target.value)}
                  />
                </div>
                <button type="submit" className="modern-send-button">
                  <i className="fas fa-paper-plane"></i>
                </button>
              </form>
            </div>
          </motion.div>
        </>
      )}
    </AnimatePresence>
  );
};

export default ModernChat;
